  retain('01-complete',{inputs,metas,before,raw,current,beforePins:{executor:hash(beforeExecutor),core:hash(beforeCore)}});assert.ok(raw.value);assert.deepEqual(current,raw);const rows=flatten(current.value);assert.equal(rows.length,inputs.length);
